:root{
/* ---- Brand ---------------------------------------------------------- */
--brand-primary:#1D6361;            /* Deep Teal — carries the brand */
--brand-primary-hover:#175250;      /* darken 8%  */
--brand-primary-pressed:#124240;    /* darken 16% */
--brand-focus:#D5EB7C;              /* focus ring */

/* ---- Surface tints (grounds & card fills, never body text) ---------- */
--surface-white:#FFFFFF;
--surface-cream:#FFFBF0;
--surface-alice:#F0F8FF;
--surface-sky:#D3E9FE;
--surface-mint:#EBFFFE;
--surface-lime:#D5EB7C;

/* ---- Accent & illustration (editorial / data only, never CTAs) ------ */
--accent-coral:#F99370;
--accent-amber:#F9B233;
--accent-olive:#A2C02B;
--accent-terracotta:#C16256;
--accent-signal-red:#CE3932;
--accent-navy-ink:#2C495B;
--accent-steel-blue:#23659B;
--accent-periwinkle:#7689D6;

/* ---- Neutrals ------------------------------------------------------- */
--black-1:#FFFFFF;
--black-divider:#D9D9D9;
--black-6:#BFBFBF;
--black-7:#8C8C8C;
--black-8:#595959;
--black-9:#454545;
--black-10:#262626;
--black-12:#000000;

/* ---- Semantic: text ------------------------------------------------- */
--text-heading:var(--brand-primary);
--text-heading-neutral:var(--black-10);
--text-body:var(--black-8);
--text-strong:var(--black-9);
--text-caption:var(--black-7);
--text-disabled:var(--black-6);
--text-on-dark:var(--surface-mint);
--text-on-dark-strong:#FFFFFF;
--text-link:var(--brand-primary);
--text-link-hover:var(--brand-primary-hover);
--text-error:var(--accent-signal-red);

/* ---- Semantic: surfaces -------------------------------------------- */
--surface-page:var(--surface-white);
--surface-card:var(--surface-white);
--surface-card-tint:var(--surface-sky);
--surface-card-warm:var(--surface-cream);
--surface-card-invert:var(--brand-primary);
--surface-section-calm:var(--surface-alice);
--surface-section-warm:var(--surface-cream);
--surface-section-dark:var(--brand-primary);
--surface-ticker:var(--surface-lime);
--surface-media:var(--surface-alice);
--surface-disabled:var(--black-divider);

/* ---- Semantic: lines ----------------------------------------------- */
--border-hairline:var(--black-divider);
--border-strong:var(--brand-primary);
--border-caution:var(--accent-terracotta);
--scrim-teal:linear-gradient(to top,rgba(29,99,97,.92) 0%,rgba(29,99,97,0) 62%); /* @kind color */
--scrim-cream:linear-gradient(to top,rgba(255,251,240,.92) 0%,rgba(255,251,240,0) 62%); /* @kind color */
}

:root{
--font-display:"Inria Serif",Georgia,"Times New Roman",serif;
--font-body:"Inria Sans","Helvetica Neue",Arial,sans-serif;
--font-ui:"Inter","Helvetica Neue",Arial,sans-serif;

--weight-regular:400;
--weight-medium:500;
--weight-bold:700;

/* Display ramp — Inria Serif Bold. size / line-height */
--type-display-size:64px;   --type-display-lh:72px;
--type-h1-size:48px;        --type-h1-lh:65px;
--type-h2-size:40px;        --type-h2-lh:54px;
--type-h3-size:36px;        --type-h3-lh:49px;
--type-h4-size:32px;        --type-h4-lh:43px;   /* Bold Italic — accent only */
--type-h5-size:24px;        --type-h5-lh:32px;
--type-h6-size:20px;        --type-h6-lh:27px;
--type-card-title-size:24px;
--type-faq-question-size:20px;

/* Body — Inria Sans */
--type-body-l-size:20px;    --type-body-l-lh:32px;
--type-body-m-size:18px;    --type-body-m-lh:29px;
--type-body-s-size:14px;    --type-body-s-lh:18px;

/* Interface — Inter */
--type-button-size:18px;    --type-button-lh:29px;
--type-nav-size:16px;       --type-nav-lh:20px;
--type-eyebrow-size:13px;   --type-eyebrow-lh:18px;
--tracking-eyebrow:2px;

--measure-copy:70ch;        /* cap running copy at 60–75 characters */
--measure-hero:639px;
}

:root{
--space-1:4px;
--space-2:8px;
--space-3:12px;
--space-4:16px;
--space-6:24px;   /* workhorse gutter */
--space-8:32px;
--space-10:40px;
--space-12:48px;
--space-16:64px;  /* section separation */
--space-20:80px;
--space-24:96px;  /* section separation */

--pad-button-y:16px;  --pad-button-x:32px;
--pad-button-compact-y:12px; --pad-button-compact-x:24px;
--pad-card:28px;
--gap-nav:41px;
--section-y:96px;
--section-y-tablet:64px;
--section-y-mobile:48px;
}

:root{
--radius-chip:4px;        /* chips, tags */
--radius-media:8px;       /* images, media */
--radius-button:10px;     /* buttons, form fields */
--radius-card-sm:12px;    /* small cards */
--radius-card:16px;       /* cards */
--radius-feature:24px;    /* feature blocks */
--radius-hero:32px;       /* hero panels */
--radius-pill:100px;      /* pills, avatars */
}

:root{
/* Shadows are almost absent in this system: cards are defined by fill and a
   1px hairline. Only floating overlays and the hover lift get a shadow. */
--shadow-none:none;
--shadow-hairline:inset 0 0 0 1px var(--border-hairline);
--shadow-lift:0 2px 8px rgba(29,99,97,.08);
--shadow-overlay:0 8px 32px rgba(29,99,97,.14);
--focus-ring:0 0 0 2px var(--surface-white),0 0 0 4px var(--brand-focus);
}

:root{
--ease-entrance:cubic-bezier(.215,.61,.355,1); /* @kind other */   /* power3.out */
--ease-hover:cubic-bezier(.25,.46,.45,.94); /* @kind other */      /* power2.out */
--dur-entrance:800ms; /* @kind other */
--dur-hover:200ms; /* @kind other */
--stagger-item:80ms; /* @kind other */
--entrance-offset:24px;
--hover-lift:2px;
--hover-scale-max:1.02; /* @kind other */
}
@media (prefers-reduced-motion:reduce){
:root{--dur-entrance:1ms; /* @kind other */
--dur-hover:1ms; /* @kind other */
--stagger-item:0ms; /* @kind other */
--entrance-offset:0px}
}

:root{
--canvas-desktop:1440px;
--container:1312px;
--container-margin:64px;
--grid-columns:12; /* @kind other */
--grid-gutter:24px;
--column:82.67px;

--bp-laptop:1280px;   /* laptop:  1024–1279 → 960 / 48 / 12 col */
--bp-tablet:1024px;   /* tablet:   768–1023 → 688 / 40 /  8 col */
--bp-mobile:768px;    /* mobile:      <768  → fluid / 24 / 4 col */
}
@media (max-width:1279px){:root{--container:960px;--container-margin:48px;--section-y:80px}}
@media (max-width:1023px){:root{--container:688px;--container-margin:40px;--grid-columns:8; /* @kind other */--section-y:64px}}
@media (max-width:767px){:root{--container:100%;--container-margin:24px;--grid-columns:4; /* @kind other */--section-y:48px}}

*,*::before,*::after{box-sizing:border-box}
body{margin:0;background:var(--surface-page);color:var(--text-body);font-family:var(--font-body);font-size:var(--type-body-m-size);line-height:var(--type-body-m-lh);-webkit-font-smoothing:antialiased;text-wrap:pretty}
h1,h2,h3,h4,h5,h6{font-family:var(--font-display);font-weight:var(--weight-bold);color:var(--text-heading);margin:0}
h1{font-size:var(--type-h1-size);line-height:var(--type-h1-lh)}
h2{font-size:var(--type-h2-size);line-height:var(--type-h2-lh)}
h3{font-size:var(--type-h3-size);line-height:var(--type-h3-lh)}
h4{font-size:var(--type-h4-size);line-height:var(--type-h4-lh);font-style:italic}
h5{font-size:var(--type-h5-size);line-height:var(--type-h5-lh)}
h6{font-size:var(--type-h6-size);line-height:var(--type-h6-lh)}
p{margin:0;max-width:var(--measure-copy)}
a{color:var(--text-link);text-decoration-thickness:1px;text-underline-offset:3px;transition:color var(--dur-hover) var(--ease-hover)}
a:hover{color:var(--text-link-hover)}
:focus-visible{outline:2px solid var(--brand-focus);outline-offset:2px}
.ps-container{width:100%;max-width:var(--container);margin-inline:auto;padding-inline:var(--container-margin)}
.ps-grid{display:grid;grid-template-columns:repeat(var(--grid-columns),1fr);gap:var(--grid-gutter)}
.ps-eyebrow{font-family:var(--font-ui);font-weight:var(--weight-medium);font-size:var(--type-eyebrow-size);line-height:var(--type-eyebrow-lh);letter-spacing:var(--tracking-eyebrow);text-transform:uppercase;color:var(--brand-primary)}
.ps-display{font-family:var(--font-display);font-weight:var(--weight-bold);font-size:var(--type-display-size);line-height:var(--type-display-lh);color:var(--text-heading)}
@media (max-width:767px){.ps-display{font-size:40px;line-height:48px}h1{font-size:34px;line-height:44px}h2{font-size:30px;line-height:40px}h3{font-size:26px;line-height:34px}}

/* Responsive layout utilities. Breakpoints follow tokens/layout.css:
   >=1280 desktop - 1024-1279 laptop - 768-1023 tablet - <768 mobile. */
.ps-grid-2{display:grid;grid-template-columns:1fr 1fr;gap:var(--space-16)}
.ps-grid-split{display:grid;grid-template-columns:1.05fr .95fr;gap:var(--space-16);align-items:center}
.ps-grid-split-rev{display:grid;grid-template-columns:.9fr 1.1fr;gap:var(--space-16);align-items:center}
.ps-grid-3{display:grid;grid-template-columns:repeat(3,1fr);gap:var(--grid-gutter)}
.ps-grid-4{display:grid;grid-template-columns:repeat(4,1fr);gap:var(--grid-gutter)}
.ps-grid-footer{display:grid;grid-template-columns:1.4fr 1fr 1fr 1.2fr;gap:var(--grid-gutter)}
.ps-collage{display:grid;grid-template-columns:1fr 1fr;gap:var(--space-4)}
@media (max-width:1279px){.ps-grid-4{grid-template-columns:repeat(3,1fr)}.ps-grid-split,.ps-grid-split-rev,.ps-grid-2{gap:var(--space-12)}}
@media (max-width:1023px){
.ps-grid-split,.ps-grid-split-rev,.ps-grid-2{grid-template-columns:1fr;gap:var(--space-12)}
.ps-grid-3,.ps-grid-4{grid-template-columns:repeat(2,1fr)}
.ps-grid-footer{grid-template-columns:1fr 1fr;row-gap:var(--space-10)}
.ps-display{font-size:44px;line-height:54px}
}
@media (max-width:767px){
.ps-grid-3,.ps-grid-4,.ps-grid-footer,.ps-collage{grid-template-columns:1fr}
}

